function ChangeArchiveHierarchy() {
  const identity = gIdentity || parent.getCurrentAccount().defaultIdentity;
  parent.gSubDialog.open(
    "chrome://messenger/content/am-archiveoptions.xhtml",
    undefined,
    { identity }
  );
